# ================= MAIN LAYOUT (AFFIANCATO) =================
col_left, col_right = st.columns([1, 1], gap="large")

with col_left:
    st.markdown('<div class="glass-card">', unsafe_allow_html=True)
    st.markdown("### 📝 Input Testo")
    text_input = st.text_area(
        "Inserisci il testo da analizzare:",
        placeholder="Scrivi qui il testo da cui estrarre le emozioni...",
        height=180
    )
    st.markdown('</div>', unsafe_allow_html=True)

with col_right:
    st.markdown('<div class="glass-card">', unsafe_allow_html=True)
    st.markdown("### 🖼️ Input Immagine")
    uploaded_image = st.file_uploader(
        "Carica un'immagine di supporto per l'analisi multimodale:",
        type=["jpg", "jpeg", "png", "webp"]
    )
    if uploaded_image is not None:
        image = Image.open(uploaded_image)
        st.image(image, use_container_width=True, caption="Immagine caricata")
    st.markdown('</div>', unsafe_allow_html=True)

# ================= BUTTON & PREDICTION SECTION =================
st.markdown("<br>", unsafe_allow_html=True)
analyze_button = st.button("Analyze Emotion 🎭")

# Sotto il bottone: Sezione per la Previsione dell'Emozione
if analyze_button:
    st.markdown("<br>", unsafe_allow_html=True)
    
    if not text_input and uploaded_image is None:
        st.warning("⚠️ Per favore, inserisci almeno un testo o carica un'immagine per procedere con l'analisi.")
    else:
        with st.spinner("Analisi multimodale delle emozioni in corso..."):
            time.sleep(1.2) # Simulazione della latenza di inferenza del modello

            # Valori simulati / di test per l'output di regressione o classificazione delle emozioni
            emotions_pred = {
                "Gioia / Happiness": 0.78,
                "Tristezza / Sadness": 0.05,
                "Rabbia / Anger": 0.02,
                "Sorpresa / Surprise": 0.15,
                "Paura / Fear": 0.00
            }

            st.markdown('<div class="glass-card glass-card-interactive">', unsafe_allow_html=True)
            st.markdown("## 📊 Previsione dell'Emozione")
            
            top_emotion = max(emotions_pred, key=emotions_pred.get)
            top_score = emotions_pred[top_emotion]
            
            st.markdown(f"""
                <div style="background: rgba(99, 102, 241, 0.15); border-left: 4px solid #6366F1; padding: 15px; border-radius: 8px; margin-bottom: 20px;">
                    <h3 style="margin:0; color: #FFFFFF;">Emozione Predominante: <b>{top_emotion}</b></h3>
                    <p style="margin:5px 0 0 0; color: #94A3B8; font-family: 'JetBrains Mono', monospace;">Score di confidenza: {top_score:.2f}</p>
                </div>
            """, unsafe_allow_html=True)

            st.markdown("### Dettaglio punteggi per emozione:")
            df_emotions = pd.DataFrame(list(emotions_pred.items()), columns=["Emozione", "Score"])
            st.bar_chart(df_emotions.set_index("Emozione"))

            st.markdown('</div>', unsafe_allow_html=True)
